    start_export: {
        parameters: {
            query?: {
                /** @description Required only when authenticating with a dashboard token; ignored for secret-key auth (the key already identifies the project). */
                project_id?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Export job accepted. Poll status_url until status is 'complete'. */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @example exp_a1b2c3d4e5f6 */
                        job_id?: string;
                        /** @example pending */
                        status?: string;
                        /** @example 128 */
                        image_count?: number;
                        /** @example /v1/export-jobs/exp_a1b2c3d4e5f6 */
                        status_url?: string;
                    };
                };
            };
            /** @description project_id required (dashboard-token auth) */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Invalid or missing credentials */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Publishable key used (secret key required) */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Project not found for this account */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description An export for this project is already in progress */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
