    claim_upload: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @description The `claim_token` returned by POST /v1/playground/upload. */
                    token: string;
                };
            };
        };
        responses: {
            /** @description Already claimed — the same image, returned without storing a second copy */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": Record<string, never>;
                };
            };
            /** @description Image saved permanently */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data?: {
                            /** @example img_a1b2c3d4e5f6 */
                            id?: string;
                            /** Format: uri */
                            url?: string;
                            /** @example image/png */
                            mime_type?: string;
                            /** @example 51234 */
                            size?: number;
                            /** @example proj_a1b2c3d4e5f6 */
                            project_id?: string;
                            /** @example false */
                            already_claimed?: boolean;
                        };
                    };
                };
            };
            /** @description Missing or invalid claim token */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description No valid session */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Storage limit reached — a plan ceiling, not a rate limit */
            402: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Unverified account at the pre-verification upload cap */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The account has no project to save into */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The temporary upload has expired and is gone */
            410: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Rate limit or monthly upload quota exceeded */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
    dashboard_upload: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "multipart/form-data": {
                    /**
                     * Format: binary
                     * @description The image file. Max 5 MB; type is detected from magic bytes.
                     */
                    file: string;
                };
            };
        };
        responses: {
            /** @description Image stored */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data?: {
                            /** @example img_a1b2c3d4e5f6 */
                            id?: string;
                            /** Format: uri */
                            url?: string;
                            /** @example image/png */
                            mime_type?: string;
                            /** @example 51234 */
                            size?: number;
                            /** @example screenshot.png */
                            filename?: string;
                            /** @example proj_a1b2c3d4e5f6 */
                            project_id?: string;
                        };
                    };
                };
            };
            /** @description No file provided, or the bytes are not a supported image */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description No valid session */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Storage limit reached — a plan ceiling, not a rate limit */
            402: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Unverified account at the pre-verification upload cap */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The account has no project to upload into */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description File larger than 5 MB */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Rate limit or monthly upload quota exceeded */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
